import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { patientApi } from '../../api/patientApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const MyPrescriptions = () => {
  const navigate = useNavigate();
  const [prescriptions, setPrescriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchPrescriptions = async () => {
      try {
        const response = await patientApi.getPrescriptions();
        if (response.success) {
          const sorted = response.prescriptions.sort((a, b) => {
            return new Date(b.createdAt) - new Date(a.createdAt);
          });
          setPrescriptions(sorted);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch prescriptions');
      } finally {
        setLoading(false);
      }
    };

    fetchPrescriptions();
  }, []);

  if (loading) return <Loader />;

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8 fade-in">
        <h1 className="text-4xl font-bold text-gray-800 mb-2">My Prescriptions</h1>
        <p className="text-gray-600 text-lg">Access your digital prescriptions with QR codes</p>
      </div>

      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      {prescriptions.length > 0 ? (
        <div className="space-y-4">
          {prescriptions.map((prescription) => (
            <Card 
              key={prescription._id}
              hover
              className="border-l-4 border-l-purple-500 hover:border-l-purple-600"
            >
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-4 mb-4">
                    <div className="w-16 h-16 bg-gradient-to-br from-purple-500 to-pink-600 rounded-full flex items-center justify-center">
                      <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                    </div>
                    <div className="flex-1">
                      <h3 className="text-xl font-bold text-gray-800 mb-1">
                        Dr. {prescription.doctor?.user?.name || 'N/A'}
                      </h3>
                      <p className="text-gray-600 text-sm">
                        {new Date(prescription.createdAt).toLocaleDateString('en-US', { 
                          weekday: 'long', 
                          year: 'numeric', 
                          month: 'long', 
                          day: 'numeric' 
                        })}
                      </p>
                    </div>
                    {prescription.qrToken && (
                      <div className="bg-green-100 px-3 py-1 rounded-full">
                        <span className="text-green-700 text-xs font-semibold flex items-center gap-1">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                          </svg>
                          QR Available
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="space-y-3">
                    <div>
                      <p className="text-gray-500 text-xs mb-1">Diagnosis</p>
                      <p className="text-gray-800 font-semibold">{prescription.diagnosis}</p>
                    </div>
                    {prescription.symptoms && (
                      <div>
                        <p className="text-gray-500 text-xs mb-1">Symptoms</p>
                        <p className="text-gray-700">{prescription.symptoms}</p>
                      </div>
                    )}
                    <div className="flex items-center gap-4 text-sm">
                      <div>
                        <p className="text-gray-500 text-xs mb-1">Medicines</p>
                        <p className="text-gray-800 font-semibold">{prescription.medicines?.length || 0} prescribed</p>
                      </div>
                      {prescription.followUpDate && (
                        <div>
                          <p className="text-gray-500 text-xs mb-1">Follow-up</p>
                          <p className="text-gray-800 font-semibold">
                            {new Date(prescription.followUpDate).toLocaleDateString()}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex flex-col gap-2">
                  {prescription.qrToken ? (
                    <button
                      onClick={() => navigate(`/patient/prescriptions/qr/${prescription.qrToken}`)}
                      className="btn btn-primary whitespace-nowrap flex items-center justify-center gap-2"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                      </svg>
                      View Prescription
                    </button>
                  ) : (
                    <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-center">
                      <p className="text-red-600 text-sm font-semibold">QR Code unavailable</p>
                    </div>
                  )}
                </div>
              </div>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <div className="text-center py-12">
            <svg className="w-16 h-16 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p className="text-gray-600 text-lg mb-2">No prescriptions found</p>
            <p className="text-gray-500 text-sm">Your prescriptions will appear here after your appointments</p>
          </div>
        </Card>
      )}
    </div>
  );
};

export default MyPrescriptions;
